//! 🎟️ Native Window authority capture retains the exact metadata roster and its genuine existing partition read.
use super::*;
use std::mem::ManuallyDrop;
use semio_framework_job::{StepContext,OriginalTurnFailure,OriginalSourceBinding,OriginalConstructionDemand,admit_original_construction};
/// 🪢️ One bounded address copier is shared by the genuine configuration and transient authority owners.
#[derive(Default)]
pub struct OriginalWindowAddressCopy{field:usize,offset:usize,source:Option<[(usize,usize);3]>,columns:usize}
impl OriginalWindowAddressCopy{
 /// 📥️ Reserves one actual string backing or copies one bounded UTF-8 fragment under the original receiving control.
 pub fn advance(&mut self,sources:&[&str],targets:&mut[&mut String],body:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if sources.len()!=targets.len()||sources.len()>3{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original Window address columns differ").into())}let identity=std::array::from_fn(|index|sources.get(index).map_or((0,0),|source|(source.as_ptr()as usize,source.len())));if self.source.is_some_and(|original|original!=identity)||self.source.is_some()&&self.columns!=sources.len(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original Window address capture changed its source columns").into())}if self.field==sources.len(){return Ok(true)}
  if self.source.is_none(){let mut output=None;admit_original_construction(cx,&mut output,OriginalConstructionDemand{items:1,copy_bytes:size_of::<Self>(),capacity_bytes:0,release_bytes:0,depth:1},|_|{self.source=Some(identity);self.columns=sources.len();Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<Self>(),..Default::default()}))})?;return Ok(false)}
  let source=sources[self.field];let target=&mut targets[self.field];if target.len()!=self.offset{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original Window address destination changed its funded prefix").into())}let scalar=2*size_of::<usize>();
  if self.offset==0&&target.capacity()<source.len(){let bytes=source.len();let mut output=None;admit_original_construction(cx,&mut output,OriginalConstructionDemand{items:1,copy_bytes:size_of::<String>(),capacity_bytes:bytes,release_bytes:0,depth:1},|_|{let previous=target.capacity();target.try_reserve_exact(bytes.saturating_sub(target.len())).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original Window address reservation refused"))?;Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<String>(),retained_capacity_bytes:target.capacity()-previous,..Default::default()}))})?;return Ok(false)}
  let mut count=source.len().saturating_sub(self.offset).min(64).min(body.saturating_sub(scalar));while count>0&&!source.is_char_boundary(self.offset+count){count-=1}if count==0&&self.offset<source.len(){return Ok(false)}let mut output=None;
  admit_original_construction(cx,&mut output,OriginalConstructionDemand{items:1,copy_bytes:scalar+count,capacity_bytes:0,release_bytes:0,depth:1},|_|{target.push_str(&source[self.offset..self.offset+count]);self.offset+=count;if self.offset==source.len(){self.field+=1;self.offset=0}Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:scalar+count,..Default::default()}))})?;Ok(self.field==sources.len())
 }
}
/// 🪟️ The source stores no cloned ViewModel or roster and owns every partially captured read until paid closure.
pub struct OriginalWindowConfigCapture{binding:Option<OriginalSourceBinding>,decoder:Option<(u64,u64)>,body:usize,view:usize,selection:semio_framework::ViewModelWindowSelection,address:OriginalWindowAddressCopy,authority:ManuallyDrop<Option<WindowConfigAuthority>>,close:semio_framework_value::retained_clone::RetainedCloneClose,ready:bool}
impl OriginalWindowConfigCapture{
 pub fn birth_demands()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<Self>(),depth:1,..Default::default()}}
 pub fn admit(cx:&mut StepContext<'_>,output:&mut Option<Self>)->Result<bool,OriginalTurnFailure>{let d=Self::birth_demands();let decoder=cx.native_receiving_identity().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"native Window capture requires its original receiving recipient"))?;let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;admit_original_construction(cx,output,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:0,release_bytes:0,depth:1},|_|Ok((Self{binding:Some(binding),decoder:Some(decoder),body,view:0,selection:Default::default(),address:Default::default(),authority:ManuallyDrop::new(None),close:Default::default(),ready:false},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})))}
 fn validate(&self,view:Option<&ViewModel>,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.is_some_and(|original|original.matches(cx))||self.decoder!=cx.native_receiving_identity()||self.view!=0&&self.view!=view.map_or(1,|view|view as*const _ as usize){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"native Window capture changed its original metadata, source or recipient").into())}Ok(())}
 /// 🧭️ Selects the addressed or focused original Window, then captures its existing typed issuer before bounded address copies.
 pub fn advance(&mut self,registry:&mut WindowConfigOwnerRegistry,view:Option<&ViewModel>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(view,cx)?;if self.ready{return Ok(true)}if self.view==0{let d=size_of::<usize>();let mut output=None;admit_original_construction(cx,&mut output,OriginalConstructionDemand{items:1,copy_bytes:d,capacity_bytes:0,release_bytes:0,depth:1},|_|{self.view=view.map_or(1,|view|view as*const _ as usize);Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d,..Default::default()}))})?;return Ok(false)}
  let Some(view)=view else{return self.mark_ready(cx)};let Some(target)=view.window_id.as_deref().or(view.focused_window_id.as_deref())else{return self.mark_ready(cx)};
  let epoch=self.binding.unwrap().generation().0;
  if !self.selection.complete(){let d=self.selection.demands(view,target,epoch,self.body)?;let grant=cx.retained_grant();let mut output=None;admit_original_construction(cx,&mut output,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let p=self.selection.advance(view,target,epoch,self.body,grant)?.progress();Ok(((),p))})?;return Ok(false)}
  let window=self.selection.selected(view,target,epoch)?.ok_or_else(||ValueError::literal(ValueRefusalKind::InvalidValue,"original target Window is absent from its ViewModel roster"))?;
  let Some(owner)=registry.owners.get_mut(window.window_kind_id.as_str())else{return self.mark_ready(cx)};
  if self.authority.is_none(){if !owner.ensure_partition(target,cx)?{return Ok(false)}owner.capture_original_header(target,cx,&mut self.authority)?;return Ok(false)}
  let authority=self.authority.as_mut().unwrap();let current=owner.borrow(target).ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"captured original Window partition is absent"))?;if current.authority!=authority.snapshot.authority||current.generation!=authority.generation||current.revision!=authority.revision{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"native Window capture partition frontier changed").into())}
  if self.address.advance(&[target,&window.window_kind_id],&mut[&mut authority.window_id,&mut authority.window_kind_id],self.body,cx)?{return self.mark_ready(cx)}Ok(false)
 }
 fn mark_ready(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let mut output=None;admit_original_construction(cx,&mut output,OriginalConstructionDemand{items:1,copy_bytes:size_of::<bool>(),capacity_bytes:0,release_bytes:0,depth:1},|_|{self.ready=true;Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<bool>(),..Default::default()}))})?;Ok(self.ready)}
 /// 📤️ The same original typed read and address backings move to the mounted authority slot.
 pub fn take_into(&mut self,output:&mut Option<WindowConfigAuthority>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.binding.is_some_and(|original|original.matches(cx))||self.decoder!=cx.native_receiving_identity(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original Window capture handoff changed its source or recipient").into())}if !self.ready||output.is_some(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original Window capture handoff changed its ready destination").into())}if self.authority.is_none(){return Ok(true)}let d=2*size_of::<WindowConfigAuthority>();admit_original_construction(cx,output,OriginalConstructionDemand{items:1,copy_bytes:d,capacity_bytes:0,release_bytes:0,depth:1},|_|Ok((self.authority.take().unwrap(),RetainedCloneProgress{copied_items:1,copied_bytes:d,..Default::default()})))}
 pub fn handoff_complete(&self)->bool{self.ready&&self.authority.is_none()}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if !self.close.is_empty(){return self.close.demands(self.body)}if self.authority.is_some(){return Ok(RetirementDemand{capacity_bytes:semio_framework_value::owned_retirement_birth_bytes::<WindowConfigAuthority>(),depth:1,..Default::default()})}Ok(RetirementDemand{copy_bytes:usize::from(self.binding.is_some())*size_of::<Self>(),depth:usize::from(self.binding.is_some()),..Default::default()})}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(true)}if !self.binding.is_some_and(|original|original.matches(cx))||self.decoder!=cx.native_receiving_identity(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"native Window capture retirement changed its source or recipient").into())}let d=self.close_demands()?;if !self.close.is_empty()||self.authority.is_some(){semio_framework_job::close_original_retained_step(cx,d,|grant|{if !self.close.is_empty(){self.close.select(self.body)?.step(grant)}else{Ok(self.close.begin_granted(&mut self.authority,grant)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}})?;return Ok(false)}semio_framework_job::close_original_retained_step(cx,d,|_|{self.binding=None;self.decoder=None;self.view=0;self.body=0;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.authority.is_none()&&self.close.is_empty()}
}

impl Drop for OriginalWindowConfigCapture{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original Window capture retains its genuine read authority");}}

